window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0ef27a8d1bd9d79f"]={"versions": [{"id": "FIG-0ef27a8d1bd9d79f", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML 2.0 Sequenzdiagramm mit Interaktionsrahmen (<code>loop</code> für Controller-Iterationen und zyklische Task-Abarbeitung), synchronen Funktionsaufrufen, Return-Pfeilen und synchronen/asynchronen Zustandsindikationen.\n</li><li><strong>Funktionale Einordnung:</strong> Detailliert den zweistufigen Cluster-Hochlauf im AUTOSAR Classic Communication Stack (<code>AUTOSAR_CP_SWS_FlexRayStateManager</code>, R23-11). Das Diagramm beschreibt das Zusammenspiel zwischen <code>FrSM</code>, <code>FrIf</code>, <code>BswM</code>, <code>ComM</code>, <code>SchM</code> und <code>Dem</code>, wenn der Controller-Parameter <code>pKeySlotOnlyEnabled == TRUE</code> konfiguriert ist. In diesem Modus nimmt der Knoten nach dem Startup zunächst nur an der Übertragung von Key-Slots (Synchronisations-/Coldstart-Frames) teil, bevor der vollständige Sende-/Empfangsbetrieb (<code>ALL_SLOTS</code>) softwaregesteuert über den <code>BswM</code> freigegeben wird.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte BSW-Module (<code>«module»</code>):</strong>\n<ul class=\"fig-list\"><li><code>ComM</code>: Communication Manager – übergeordneter Koordinator des Kommunikationsmodus (<code>COMM_FULL_COM</code>).\n</li><li><code>BswM</code>: Basic Software Mode Manager – arbitriert Systemmodi, führt Schedule-Kompatibilitätsprüfungen durch und triggert Moduswechsel.\n</li><li><code>SchM</code>: BSW Scheduler – taktet die zyklische Ausführung des <code>FrSM</code>.\n</li><li><code>Dem</code>: Diagnostic Event Manager – erfasst diagnostische Ereignisse des Cluster-Hochlaufs (<code>FRSM_E_CLUSTER_STARTUP</code>).\n</li><li><code>FrSM</code>: FlexRay State Manager – steuert den Protokollzustandsautomaten des FlexRay-Clusters.\n</li><li><code>FrIf</code>: FlexRay Interface – hardwareabstrahierende Schnittstelle zu den FlexRay-Controllern (<code>CC</code>) des Clusters.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Service-APIs:</strong>\n<ul class=\"fig-list\"><li><code>SchM</code> → <code>FrSM</code>: <code>FrSM_MainFunction_&lt;FrSMCluster.ShortName&gt;()</code> (zyklischer Task-Trigger).\n</li><li><code>FrSM</code> → <code>FrIf</code>:\n<ul class=\"fig-list\"><li><code>FrIf_GetPOCStatus(CtrlIdx, POCStatusPtr)</code>: Abfrage des Protocol Operation Control (POC) Status für jeden Controller (<code>CtrlIdx</code>) des Clusters.\n</li><li><code>FrIf_SetState(ClstIdx, FRIF_GOTO_ONLINE)</code>: Anforderung des Online-Zustands für den Cluster (<code>ClstIdx</code>).\n</li><li><code>FrIf_AllSlots(CtrlIdx)</code>: Befehl an den FlexRay-Treiber zur Freigabe aller Slots.\n</li></ul>\n</li><li><code>FrSM</code> → <code>Dem</code>: <code>Dem_SetEventStatus(FRSM_E_CLUSTER_STARTUP, PASSED)</code>.\n</li><li><code>FrSM</code> → <code>BswM</code>:\n<ul class=\"fig-list\"><li><code>BswM_FrSM_CurrentState(FRSM_ONLINE_KEYSLOT_ONLY)</code>: Indikation des eingeschränkten Sendemodus.\n</li><li><code>BswM_FrSM_CurrentState(FRSM_ONLINE)</code>: Indikation des vollen Kommunikationsmodus.\n</li></ul>\n</li><li><code>BswM</code> → <code>FrSM</code>: <code>FrSm_AllSlots(NetworkHandle)</code>: Request zur Freischaltung sämtlicher statischer/dynamischer Slots.\n</li><li><code>FrSM</code> → <code>ComM</code>: <code>ComM_BusSM_ModeIndication(NetworkHandle, COMM_FULL_COM)</code>.\n</li></ul>\n</li><li><strong>Kardinalitäten &amp; Zuordnungen:</strong>\n<ul class=\"fig-list\"><li>1 Cluster (<code>ClstIdx</code> / <code>NetworkHandle</code>) ↔ 1..n FlexRay-Controller (<code>CtrlIdx</code> / <code>CC</code>). Jede POC-Abfrage sowie die <code>AllSlots</code>-Aktivierung wird in einer Schleife über alle zugewiesenen <code>CtrlIdx</code> ausgeführt.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Startup-Polling:</strong>\n<ul class=\"fig-list\"><li><code>SchM</code> triggert periodisch <code>FrSM_MainFunction_&lt;FrSMCluster.ShortName&gt;()</code>.\n</li><li><code>FrSM</code> iteriert über alle <code>CtrlIdx</code> des Clusters und ruft <code>FrIf_GetPOCStatus(CtrlIdx, POCStatusPtr)</code> auf.\n</li><li>Solange der Controller <code>FR_POCSTATE_STARTUP</code> meldet, verbleibt der <code>FrSM</code> im Startup-Wartezustand.\n</li></ul>\n</li><li><strong>Erreichen von <code>KEYSLOT_ONLY</code>:</strong>\n<ul class=\"fig-list\"><li>Nach erfolgreicher Synchronisation meldet <code>FrIf_GetPOCStatus</code>: <code>FR_POCSTATE_NORMAL_ACTIVE</code> mit <code>SlotMode = FR_SLOTMODE_KEYSLOT</code> (bedingt durch <code>pKeySlotOnlyEnabled == TRUE</code>).\n</li><li><code>FrSM</code> setzt den Interface-Zustand via <code>FrIf_SetState(ClstIdx, FRIF_GOTO_ONLINE)</code>.\n</li><li><code>FrSM</code> meldet den erfolgreichen Hochlauf an das <code>Dem</code> via <code>Dem_SetEventStatus(FRSM_E_CLUSTER_STARTUP, PASSED)</code>.\n</li><li><code>FrSM</code> meldet an den <code>BswM</code>: <code>BswM_FrSM_CurrentState(FRSM_ONLINE_KEYSLOT_ONLY)</code>.\n</li></ul>\n</li><li><strong>Schedule-Prüfung &amp; All-Slots-Aktivierung:</strong>\n<ul class=\"fig-list\"><li>Der <code>BswM</code> verarbeitet die Information (z. B. Validierung des empfangenen FlexRay-Schedules anhand der im Key-Slot übertragenen Daten).\n</li><li>Bei erfolgreicher Prüfung ruft der <code>BswM</code> die API <code>FrSm_AllSlots(NetworkHandle)</code> synchron auf.\n</li><li><code>FrSM</code> delegiert dies in einer Schleife an alle zugeordneten Controller: <code>FrIf_AllSlots(CtrlIdx)</code>.\n</li></ul>\n</li><li><strong>Vollständiger Online-Übergang:</strong>\n<ul class=\"fig-list\"><li>Im nächsten Zyklus der <code>FrSM_MainFunction_&lt;FrSMCluster.ShortName&gt;()</code> liefert <code>FrIf_GetPOCStatus</code>: <code>FR_POCSTATE_NORMAL_ACTIVE</code> mit <code>SlotMode = FR_SLOTMODE_ALL</code>.\n</li><li><code>FrSM</code> bestätigt dem <code>ComM</code> die volle Kommunikation via <code>ComM_BusSM_ModeIndication(NetworkHandle, COMM_FULL_COM)</code>.\n</li><li><code>FrSM</code> indiziert dem <code>BswM</code> den Endzustand via <code>BswM_FrSM_CurrentState(FRSM_ONLINE)</code>.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Konfigurationsabhängigkeit:</strong>\n<ul class=\"fig-list\"><li>Das dargestellte Verhalten wird primär durch den FlexRay-Controller-Hardwareparameter <code>pKeySlotOnlyEnabled</code> (FIBEX/ARXML) gesteuert.\n</li><li>Im <code>FrSM</code> muss der Key-Slot-Only-Support aktiviert sein (<code>FrSMKeySlotOnlyModeEnabled == TRUE</code>).\n</li></ul>\n</li><li><strong>BswM-Regelwerk:</strong>\n<ul class=\"fig-list\"><li>Der Entwickler muss im <code>BswM</code> explizite Mode Rules konfigurieren, die auf die Indikation <code>FRSM_ONLINE_KEYSLOT_ONLY</code> reagieren, die Schedule-Validierung anstoßen und die Action <code>FrSm_AllSlots</code> ausführen. Ohne diesen BswM-Aufruf verharrt der Cluster im Key-Slot-Betrieb; reguläre PDUs werden weder gesendet noch von ComM freigegeben.\n</li></ul>\n</li><li><strong>ComM-Synchronisation:</strong>\n<ul class=\"fig-list\"><li><code>ComM_BusSM_ModeIndication(COMM_FULL_COM)</code> wird <strong>erst</strong> nach Bestätigung von <code>FR_SLOTMODE_ALL</code> durch die Hardware abgesetzt. Bis zu diesem Zeitpunkt bleibt die PDU-Kommunikation für Standard-Frames im Com/PduR-Stack blockiert.\n</li></ul>\n</li><li><strong>Diagnose (<code>Dem</code>):</strong>\n<ul class=\"fig-list\"><li>Das Dem-Event <code>FRSM_E_CLUSTER_STARTUP</code> wird bereits beim Übergang in <code>FR_SLOTMODE_KEYSLOT</code> auf <code>PASSED</code> gesetzt, da der physikalische Cluster-Startup (Coldstart/Sync) zu diesem Zeitpunkt protokollseitig abgeschlossen ist.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-a77b98eec8964fda", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML 2.0 Sequenzdiagramm mit Interaktionsrahmen (<code>loop</code> für Controller-Iterationen und zyklische Task-Abarbeitung), synchronen Funktionsaufrufen, Return-Pfeilen und synchronen/asynchronen Zustandsindikationen.\n</li><li><strong>Funktionale Einordnung:</strong> Detailliert den zweistufigen Cluster-Hochlauf im AUTOSAR Classic Communication Stack (<code>AUTOSAR_CP_SWS_FlexRayStateManager</code>, R23-11). Das Diagramm beschreibt das Zusammenspiel zwischen <code>FrSM</code>, <code>FrIf</code>, <code>BswM</code>, <code>ComM</code>, <code>SchM</code> und <code>Dem</code>, wenn der Controller-Parameter <code>pKeySlotOnlyEnabled == TRUE</code> konfiguriert ist. In diesem Modus nimmt der Knoten nach dem Startup zunächst nur an der Übertragung von Key-Slots (Synchronisations-/Coldstart-Frames) teil, bevor der vollständige Sende-/Empfangsbetrieb (<code>ALL_SLOTS</code>) softwaregesteuert über den <code>BswM</code> freigegeben wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte BSW-Module (<code>«module»</code>):</strong>\n<ul class=\"fig-list\"><li><code>ComM</code>: Communication Manager – übergeordneter Koordinator des Kommunikationsmodus (<code>COMM_FULL_COM</code>).\n</li><li><code>BswM</code>: Basic Software Mode Manager – arbitriert Systemmodi, führt Schedule-Kompatibilitätsprüfungen durch und triggert Moduswechsel.\n</li><li><code>SchM</code>: BSW Scheduler – taktet die zyklische Ausführung des <code>FrSM</code>.\n</li><li><code>Dem</code>: Diagnostic Event Manager – erfasst diagnostische Ereignisse des Cluster-Hochlaufs (<code>FRSM_E_CLUSTER_STARTUP</code>).\n</li><li><code>FrSM</code>: FlexRay State Manager – steuert den Protokollzustandsautomaten des FlexRay-Clusters.\n</li><li><code>FrIf</code>: FlexRay Interface – hardwareabstrahierende Schnittstelle zu den FlexRay-Controllern (<code>CC</code>) des Clusters.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Service-APIs:</strong>\n<ul class=\"fig-list\"><li><code>SchM</code> → <code>FrSM</code>: <code>FrSM_MainFunction_&lt;FrSMCluster.ShortName&gt;()</code> (zyklischer Task-Trigger).\n</li><li><code>FrSM</code> → <code>FrIf</code>:\n<ul class=\"fig-list\"><li><code>FrIf_GetPOCStatus(CtrlIdx, POCStatusPtr)</code>: Abfrage des Protocol Operation Control (POC) Status für jeden Controller (<code>CtrlIdx</code>) des Clusters.\n</li><li><code>FrIf_SetState(ClstIdx, FRIF_GOTO_ONLINE)</code>: Anforderung des Online-Zustands für den Cluster (<code>ClstIdx</code>).\n</li><li><code>FrIf_AllSlots(CtrlIdx)</code>: Befehl an den FlexRay-Treiber zur Freigabe aller Slots.\n</li></ul>\n</li><li><code>FrSM</code> → <code>Dem</code>: <code>Dem_SetEventStatus(FRSM_E_CLUSTER_STARTUP, PASSED)</code>.\n</li><li><code>FrSM</code> → <code>BswM</code>:\n<ul class=\"fig-list\"><li><code>BswM_FrSM_CurrentState(FRSM_ONLINE_KEYSLOT_ONLY)</code>: Indikation des eingeschränkten Sendemodus.\n</li><li><code>BswM_FrSM_CurrentState(FRSM_ONLINE)</code>: Indikation des vollen Kommunikationsmodus.\n</li></ul>\n</li><li><code>BswM</code> → <code>FrSM</code>: <code>FrSm_AllSlots(NetworkHandle)</code>: Request zur Freischaltung sämtlicher statischer/dynamischer Slots.\n</li><li><code>FrSM</code> → <code>ComM</code>: <code>ComM_BusSM_ModeIndication(NetworkHandle, COMM_FULL_COM)</code>.\n</li></ul>\n</li><li><strong>Kardinalitäten &amp; Zuordnungen:</strong>\n<ul class=\"fig-list\"><li>1 Cluster (<code>ClstIdx</code> / <code>NetworkHandle</code>) ↔ 1..n FlexRay-Controller (<code>CtrlIdx</code> / <code>CC</code>). Jede POC-Abfrage sowie die <code>AllSlots</code>-Aktivierung wird in einer Schleife über alle zugewiesenen <code>CtrlIdx</code> ausgeführt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Startup-Polling:</strong>\n<ul class=\"fig-list\"><li><code>SchM</code> triggert periodisch <code>FrSM_MainFunction_&lt;FrSMCluster.ShortName&gt;()</code>.\n</li><li><code>FrSM</code> iteriert über alle <code>CtrlIdx</code> des Clusters und ruft <code>FrIf_GetPOCStatus(CtrlIdx, POCStatusPtr)</code> auf.\n</li><li>Solange der Controller <code>FR_POCSTATE_STARTUP</code> meldet, verbleibt der <code>FrSM</code> im Startup-Wartezustand.\n</li></ul>\n</li><li><strong>Erreichen von <code>KEYSLOT_ONLY</code>:</strong>\n<ul class=\"fig-list\"><li>Nach erfolgreicher Synchronisation meldet <code>FrIf_GetPOCStatus</code>: <code>FR_POCSTATE_NORMAL_ACTIVE</code> mit <code>SlotMode = FR_SLOTMODE_KEYSLOT</code> (bedingt durch <code>pKeySlotOnlyEnabled == TRUE</code>).\n</li><li><code>FrSM</code> setzt den Interface-Zustand via <code>FrIf_SetState(ClstIdx, FRIF_GOTO_ONLINE)</code>.\n</li><li><code>FrSM</code> meldet den erfolgreichen Hochlauf an das <code>Dem</code> via <code>Dem_SetEventStatus(FRSM_E_CLUSTER_STARTUP, PASSED)</code>.\n</li><li><code>FrSM</code> meldet an den <code>BswM</code>: <code>BswM_FrSM_CurrentState(FRSM_ONLINE_KEYSLOT_ONLY)</code>.\n</li></ul>\n</li><li><strong>Schedule-Prüfung &amp; All-Slots-Aktivierung:</strong>\n<ul class=\"fig-list\"><li>Der <code>BswM</code> verarbeitet die Information (z. B. Validierung des empfangenen FlexRay-Schedules anhand der im Key-Slot übertragenen Daten).\n</li><li>Bei erfolgreicher Prüfung ruft der <code>BswM</code> die API <code>FrSm_AllSlots(NetworkHandle)</code> synchron auf.\n</li><li><code>FrSM</code> delegiert dies in einer Schleife an alle zugeordneten Controller: <code>FrIf_AllSlots(CtrlIdx)</code>.\n</li></ul>\n</li><li><strong>Vollständiger Online-Übergang:</strong>\n<ul class=\"fig-list\"><li>Im nächsten Zyklus der <code>FrSM_MainFunction_&lt;FrSMCluster.ShortName&gt;()</code> liefert <code>FrIf_GetPOCStatus</code>: <code>FR_POCSTATE_NORMAL_ACTIVE</code> mit <code>SlotMode = FR_SLOTMODE_ALL</code>.\n</li><li><code>FrSM</code> bestätigt dem <code>ComM</code> die volle Kommunikation via <code>ComM_BusSM_ModeIndication(NetworkHandle, COMM_FULL_COM)</code>.\n</li><li><code>FrSM</code> indiziert dem <code>BswM</code> den Endzustand via <code>BswM_FrSM_CurrentState(FRSM_ONLINE)</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Konfigurationsabhängigkeit:</strong>\n<ul class=\"fig-list\"><li>Das dargestellte Verhalten wird primär durch den FlexRay-Controller-Hardwareparameter <code>pKeySlotOnlyEnabled</code> (FIBEX/ARXML) gesteuert.\n</li><li>Im <code>FrSM</code> muss der Key-Slot-Only-Support aktiviert sein (<code>FrSMKeySlotOnlyModeEnabled == TRUE</code>).\n</li></ul>\n</li><li><strong>BswM-Regelwerk:</strong>\n<ul class=\"fig-list\"><li>Der Entwickler muss im <code>BswM</code> explizite Mode Rules konfigurieren, die auf die Indikation <code>FRSM_ONLINE_KEYSLOT_ONLY</code> reagieren, die Schedule-Validierung anstoßen und die Action <code>FrSm_AllSlots</code> ausführen. Ohne diesen BswM-Aufruf verharrt der Cluster im Key-Slot-Betrieb; reguläre PDUs werden weder gesendet noch von ComM freigegeben.\n</li></ul>\n</li><li><strong>ComM-Synchronisation:</strong>\n<ul class=\"fig-list\"><li><code>ComM_BusSM_ModeIndication(COMM_FULL_COM)</code> wird <strong>erst</strong> nach Bestätigung von <code>FR_SLOTMODE_ALL</code> durch die Hardware abgesetzt. Bis zu diesem Zeitpunkt bleibt die PDU-Kommunikation für Standard-Frames im Com/PduR-Stack blockiert.\n</li></ul>\n</li><li><strong>Diagnose (<code>Dem</code>):</strong>\n<ul class=\"fig-list\"><li>Das Dem-Event <code>FRSM_E_CLUSTER_STARTUP</code> wird bereits beim Übergang in <code>FR_SLOTMODE_KEYSLOT</code> auf <code>PASSED</code> gesetzt, da der physikalische Cluster-Startup (Coldstart/Sync) zu diesem Zeitpunkt protokollseitig abgeschlossen ist.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-16e4b2610c5cf348", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML 2.0 Sequenzdiagramm mit Interaktionsrahmen (<code>loop</code> für Controller-Iterationen und zyklische Task-Abarbeitung), synchronen Funktionsaufrufen, Return-Pfeilen und synchronen/asynchronen Zustandsindikationen.\n</li><li><strong>Funktionale Einordnung:</strong> Detailliert den zweistufigen Cluster-Hochlauf im AUTOSAR Classic Communication Stack (<code>AUTOSAR_CP_SWS_FlexRayStateManager</code>, R23-11). Das Diagramm beschreibt das Zusammenspiel zwischen <code>FrSM</code>, <code>FrIf</code>, <code>BswM</code>, <code>ComM</code>, <code>SchM</code> und <code>Dem</code>, wenn der Controller-Parameter <code>pKeySlotOnlyEnabled == TRUE</code> konfiguriert ist. In diesem Modus nimmt der Knoten nach dem Startup zunächst nur an der Übertragung von Key-Slots (Synchronisations-/Coldstart-Frames) teil, bevor der vollständige Sende-/Empfangsbetrieb (<code>ALL_SLOTS</code>) softwaregesteuert über den <code>BswM</code> freigegeben wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Beteiligte BSW-Module (<code>«module»</code>):</strong>\n<ul class=\"fig-list\"><li><code>ComM</code>: Communication Manager – übergeordneter Koordinator des Kommunikationsmodus (<code>COMM_FULL_COM</code>).\n</li><li><code>BswM</code>: Basic Software Mode Manager – arbitriert Systemmodi, führt Schedule-Kompatibilitätsprüfungen durch und triggert Moduswechsel.\n</li><li><code>SchM</code>: BSW Scheduler – taktet die zyklische Ausführung des <code>FrSM</code>.\n</li><li><code>Dem</code>: Diagnostic Event Manager – erfasst diagnostische Ereignisse des Cluster-Hochlaufs (<code>FRSM_E_CLUSTER_STARTUP</code>).\n</li><li><code>FrSM</code>: FlexRay State Manager – steuert den Protokollzustandsautomaten des FlexRay-Clusters.\n</li><li><code>FrIf</code>: FlexRay Interface – hardwareabstrahierende Schnittstelle zu den FlexRay-Controllern (<code>CC</code>) des Clusters.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Service-APIs:</strong>\n<ul class=\"fig-list\"><li><code>SchM</code> → <code>FrSM</code>: <code>FrSM_MainFunction_&lt;FrSMCluster.ShortName&gt;()</code> (zyklischer Task-Trigger).\n</li><li><code>FrSM</code> → <code>FrIf</code>:\n<ul class=\"fig-list\"><li><code>FrIf_GetPOCStatus(CtrlIdx, POCStatusPtr)</code>: Abfrage des Protocol Operation Control (POC) Status für jeden Controller (<code>CtrlIdx</code>) des Clusters.\n</li><li><code>FrIf_SetState(ClstIdx, FRIF_GOTO_ONLINE)</code>: Anforderung des Online-Zustands für den Cluster (<code>ClstIdx</code>).\n</li><li><code>FrIf_AllSlots(CtrlIdx)</code>: Befehl an den FlexRay-Treiber zur Freigabe aller Slots.\n</li></ul>\n</li><li><code>FrSM</code> → <code>Dem</code>: <code>Dem_SetEventStatus(FRSM_E_CLUSTER_STARTUP, PASSED)</code>.\n</li><li><code>FrSM</code> → <code>BswM</code>:\n<ul class=\"fig-list\"><li><code>BswM_FrSM_CurrentState(FRSM_ONLINE_KEYSLOT_ONLY)</code>: Indikation des eingeschränkten Sendemodus.\n</li><li><code>BswM_FrSM_CurrentState(FRSM_ONLINE)</code>: Indikation des vollen Kommunikationsmodus.\n</li></ul>\n</li><li><code>BswM</code> → <code>FrSM</code>: <code>FrSm_AllSlots(NetworkHandle)</code>: Request zur Freischaltung sämtlicher statischer/dynamischer Slots.\n</li><li><code>FrSM</code> → <code>ComM</code>: <code>ComM_FrSM_ModeIndication(NetworkHandle, COMM_FULL_COM)</code>.\n</li></ul>\n</li><li><strong>Kardinalitäten &amp; Zuordnungen:</strong>\n<ul class=\"fig-list\"><li>1 Cluster (<code>ClstIdx</code> / <code>NetworkHandle</code>) ↔ 1..n FlexRay-Controller (<code>CtrlIdx</code> / <code>CC</code>). Jede POC-Abfrage sowie die <code>AllSlots</code>-Aktivierung wird in einer Schleife über alle zugewiesenen <code>CtrlIdx</code> ausgeführt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Startup-Polling:</strong>\n<ul class=\"fig-list\"><li><code>SchM</code> triggert periodisch <code>FrSM_MainFunction_&lt;FrSMCluster.ShortName&gt;()</code>.\n</li><li><code>FrSM</code> iteriert über alle <code>CtrlIdx</code> des Clusters und ruft <code>FrIf_GetPOCStatus(CtrlIdx, POCStatusPtr)</code> auf.\n</li><li>Solange der Controller <code>FR_POCSTATE_STARTUP</code> meldet, verbleibt der <code>FrSM</code> im Startup-Wartezustand.\n</li></ul>\n</li><li><strong>Erreichen von <code>KEYSLOT_ONLY</code>:</strong>\n<ul class=\"fig-list\"><li>Nach erfolgreicher Synchronisation meldet <code>FrIf_GetPOCStatus</code>: <code>FR_POCSTATE_NORMAL_ACTIVE</code> mit <code>SlotMode = FR_SLOTMODE_KEYSLOT</code> (bedingt durch <code>pKeySlotOnlyEnabled == TRUE</code>).\n</li><li><code>FrSM</code> setzt den Interface-Zustand via <code>FrIf_SetState(ClstIdx, FRIF_GOTO_ONLINE)</code>.\n</li><li><code>FrSM</code> meldet den erfolgreichen Hochlauf an das <code>Dem</code> via <code>Dem_SetEventStatus(FRSM_E_CLUSTER_STARTUP, PASSED)</code>.\n</li><li><code>FrSM</code> meldet an den <code>BswM</code>: <code>BswM_FrSM_CurrentState(FRSM_ONLINE_KEYSLOT_ONLY)</code>.\n</li></ul>\n</li><li><strong>Schedule-Prüfung &amp; All-Slots-Aktivierung:</strong>\n<ul class=\"fig-list\"><li>Der <code>BswM</code> verarbeitet die Information (z. B. Validierung des empfangenen FlexRay-Schedules anhand der im Key-Slot übertragenen Daten).\n</li><li>Bei erfolgreicher Prüfung ruft der <code>BswM</code> die API <code>FrSm_AllSlots(NetworkHandle)</code> synchron auf.\n</li><li><code>FrSM</code> delegiert dies in einer Schleife an alle zugeordneten Controller: <code>FrIf_AllSlots(CtrlIdx)</code>.\n</li></ul>\n</li><li><strong>Vollständiger Online-Übergang:</strong>\n<ul class=\"fig-list\"><li>Im nächsten Zyklus der <code>FrSM_MainFunction_&lt;FrSMCluster.ShortName&gt;()</code> liefert <code>FrIf_GetPOCStatus</code>: <code>FR_POCSTATE_NORMAL_ACTIVE</code> mit <code>SlotMode = FR_SLOTMODE_ALL</code>.\n</li><li><code>FrSM</code> bestätigt dem <code>ComM</code> die volle Kommunikation via <code>ComM_FrSM_ModeIndication(NetworkHandle, COMM_FULL_COM)</code>.\n</li><li><code>FrSM</code> indiziert dem <code>BswM</code> den Endzustand via <code>BswM_FrSM_CurrentState(FRSM_ONLINE)</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Konfigurationsabhängigkeit:</strong>\n<ul class=\"fig-list\"><li>Das dargestellte Verhalten wird primär durch den FlexRay-Controller-Hardwareparameter <code>pKeySlotOnlyEnabled</code> (FIBEX/ARXML) gesteuert.\n</li><li>Im <code>FrSM</code> muss der Key-Slot-Only-Support aktiviert sein (<code>FrSMKeySlotOnlyModeEnabled == TRUE</code>).\n</li></ul>\n</li><li><strong>BswM-Regelwerk:</strong>\n<ul class=\"fig-list\"><li>Der Entwickler muss im <code>BswM</code> explizite Mode Rules konfigurieren, die auf die Indikation <code>FRSM_ONLINE_KEYSLOT_ONLY</code> reagieren, die Schedule-Validierung anstoßen und die Action <code>FrSm_AllSlots</code> ausführen. Ohne diesen BswM-Aufruf verharrt der Cluster im Key-Slot-Betrieb; reguläre PDUs werden weder gesendet noch von ComM freigegeben.\n</li></ul>\n</li><li><strong>ComM-Synchronisation:</strong>\n<ul class=\"fig-list\"><li><code>ComM_FrSM_ModeIndication(COMM_FULL_COM)</code> wird <strong>erst</strong> nach Bestätigung von <code>FR_SLOTMODE_ALL</code> durch die Hardware abgesetzt. Bis zu diesem Zeitpunkt bleibt die PDU-Kommunikation für Standard-Frames im Com/PduR-Stack blockiert.\n</li></ul>\n</li><li><strong>Diagnose (<code>Dem</code>):</strong>\n<ul class=\"fig-list\"><li>Das Dem-Event <code>FRSM_E_CLUSTER_STARTUP</code> wird bereits beim Übergang in <code>FR_SLOTMODE_KEYSLOT</code> auf <code>PASSED</code> gesetzt, da der physikalische Cluster-Startup (Coldstart/Sync) zu diesem Zeitpunkt protokollseitig abgeschlossen ist.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-0ef27a8d1bd9d79f", "to": "FIG-a77b98eec8964fda", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a77b98eec8964fda", "to": "FIG-16e4b2610c5cf348", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Schnittstelle FrSM -&gt; ComM: Aufruf von <code>ComM_BusSM_ModeIndication(NetworkHandle, COMM_FULL_COM)</code> durch spezifische API <code>ComM_FrSM_ModeIndication(NetworkHandle, COMM_FULL_COM)</code> ersetzt.\n</li></ul>"}]};
